from typing import List

class Solution:
    def twoSum(self, numbers: List[int], target: int) -> List[int]:
        n = len(numbers)
        for i in range(n):
            for j in range(i + 1, n):
                # Return 1-indexed positions as required.
                if numbers[i] + numbers[j] == target:
                    return [i + 1, j + 1]
        return []

